VALUES (74879, 'tt1827487', NULL, 'Once Upon a Time in Anatolia', 'Bir Zamanlar Anadolu''da', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/bN84guFndgvtWIvFC7sTD8AAJDE.jpg', 'https://image.tmdb.org/t/p/original/213Gdu9zjGsVeWQl6p5gJrBq8n8.jpg', 'A group of men lead a search for a victim of a murder to whom a suspect named Kenan and his mentally challenged brother confessed. However, the search is proving more difficult than expected as Kenan is fuzzy as to the body''s location. As the group continues looking and the night begins dragging on, its members can''t help but chat with each other about everyday life, as the conversations turn more and more serious, revealing their deeper secrets and profound stories.', NULL, NULL, 2.7099, 7.475, 0, 6.91, '2026-08-10 02:34:01', '2026-10-13 02:06:20')
